using DTBK.Domain;
namespace DTBK.Coefficient;
public sealed class CoefficientEngine:ICoefficientProvider
{
    private static readonly CoefficientRule[] DefaultRules={new(1,CoefficientType.Location,"LOC-NORMAL","Vùng đồng bằng / bình thường",1.00m,null,LocationType.Normal,"Hệ số vị trí bình thường","TT36/2026",true,10),new(2,CoefficientType.Location,"LOC-MOUNTAIN","Vùng núi / cao nguyên",1.10m,null,LocationType.Mountain,"Hệ số vùng núi","TT36/2026",true,10),new(3,CoefficientType.Location,"LOC-BORDER","Vùng biên giới",1.15m,null,LocationType.Border,"Hệ số biên giới","TT36/2026",true,10),new(4,CoefficientType.Location,"LOC-OFFSHORE","Ngoài khơi",1.25m,null,LocationType.Offshore,"Hệ số ngoài khơi","TT36/2026",true,10),new(5,CoefficientType.Location,"LOC-ISLAND","Hải đảo",1.30m,null,LocationType.Island,"Hệ số hải đảo","TT36/2026",true,10),new(10,CoefficientType.Difficulty,"DIFF-NORMAL","Điều kiện thi công bình thường",1.00m,null,null,"Không phụ trội","TT36/2026",true,20),new(11,CoefficientType.Difficulty,"DIFF-HARD","Điều kiện thi công khó khăn",1.08m,null,null,"Địa hình phức tạp, giao thông hạn chế","TT36/2026",true,20),new(12,CoefficientType.Complexity,"CPLX-HIGH","Công trình phức tạp cao",1.05m,WorkType.Industrial,null,"Công nghệ cao, yêu cầu kỹ thuật nghiêm ngặt","TT36/2026",true,30)};
    public CoefficientSet Resolve(WorkType workType,LocationType location,DateTime effectiveDate,IEnumerable<string>? extraCodes=null){var selected=new List<CoefficientRule>();var loc=DefaultRules.FirstOrDefault(r=>r.Type==CoefficientType.Location&&r.ApplicableLocation==location&&r.IsActive)??DefaultRules.First(r=>r.Code=="LOC-NORMAL");selected.Add(loc);selected.Add(DefaultRules.First(r=>r.Code=="DIFF-NORMAL"));var cplx=DefaultRules.FirstOrDefault(r=>r.Type==CoefficientType.Complexity&&r.ApplicableWorkType==workType&&r.IsActive);if(cplx is not null)selected.Add(cplx);if(extraCodes is not null)foreach(var code in extraCodes){var extra=DefaultRules.FirstOrDefault(r=>r.Code.Equals(code,StringComparison.OrdinalIgnoreCase)&&r.IsActive);if(extra is not null&&!selected.Any(s=>s.Code==extra.Code))selected.Add(extra);}return new CoefficientSet(selected.OrderBy(r=>r.Priority).ToList());}
    public static decimal Apply(decimal baseAmount,CoefficientSet set)=>Math.Round(baseAmount*set.TotalFactor,0,MidpointRounding.AwayFromZero);
}
